import{_ as a}from"./chunks/initial-pose.DaOVbNCH.js";import{c as t,Q as n,j as r,m as o}from"./chunks/framework.DjobWxAB.js";const p=JSON.parse('{"title":"Maintenance Safety","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/Safety/maintenance-safety.md","filePath":"manual/Safety/maintenance-safety.md","lastUpdated":1779182288000}'),l={name:"manual/Safety/maintenance-safety.md"};function i(s,e,c,m,d,f){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="maintenance-safety" tabindex="-1">Maintenance Safety <a class="header-anchor" href="#maintenance-safety" aria-label="Permalink to &quot;Maintenance Safety&quot;">​</a></h1><p>Safety rules for maintenance such as battery replacement, foot/bumper/leg module replacement, and calibration.</p><h2 id="before-work" tabindex="-1">Before work <a class="header-anchor" href="#before-work" aria-label="Permalink to &quot;Before work&quot;">​</a></h2><div class="custom-block safety-label-block" style="padding:1rem 1.5rem;border-radius:8px;background:rgba(211, 84, 0, 0.12);border-left:4px solid #d35400;display:flex;gap:1rem;align-items:stretch;"><div style="display:flex;align-items:center;justify-content:center;flex-shrink:0;width:2.5rem;"><span style="font-size:2.5rem;line-height:1;color:#d35400;" aria-hidden="true">⚠</span></div><div style="flex:1;"><p class="custom-block-title">CAUTION</p><p>1) Before maintenance, turn robot power off and disconnect the battery if needed.<br>2) Touch parts only after the robot has fully stopped. Confirm joints are in a safe state.<br>3) Use only specified tools and procedures. Disassembly or assembly not in the manual can cause damage or injury.</p></div></div><h2 id="battery-and-electrical" tabindex="-1">Battery and electrical <a class="header-anchor" href="#battery-and-electrical" aria-label="Permalink to &quot;Battery and electrical&quot;">​</a></h2><ul><li><strong>Battery replacement</strong>: Follow <a href="/RBQ/manual/Safety/battery-handling.html">Battery Handling Precautions</a> and <a href="/RBQ/manual/Maintenance/battery.html">Battery Replacement</a>.</li><li><strong>Cables and connectors</strong>: When <a href="/RBQ/manual/Maintenance/connector.html">detaching connectors</a>, do not pull on cables-use the specified method.</li></ul><h2 id="mechanical-parts" tabindex="-1">Mechanical parts <a class="header-anchor" href="#mechanical-parts" aria-label="Permalink to &quot;Mechanical parts&quot;">​</a></h2><ul><li><strong>Legs, feet, bumper</strong>: When replacing <a href="/RBQ/manual/Maintenance/foot.html">feet</a>, <a href="/RBQ/manual/Maintenance/leg-module.html">leg modules</a>, or <a href="/RBQ/manual/Maintenance/bumper.html">stand and bumper</a>, confirm screws and fasteners are tight-loose parts can come off during operation.</li><li><strong>Calibration</strong>: Perform <a href="/RBQ/manual/Troubleshooting/calibration-tuning.html">calibration and tuning</a> per the manual and GUI only when the robot is stable.</li></ul><h2 id="work-environment" tabindex="-1">Work environment <a class="header-anchor" href="#work-environment" aria-label="Permalink to &quot;Work environment&quot;">​</a></h2><ul><li><strong>Flat surface</strong>: Work on a level, stable surface-the robot can fall on a slope.</li><li><strong>Solo heavy lifting</strong>: When lifting heavy parts alone, get help or use equipment to avoid injury.</li></ul><figure><img src="'+a+'" alt="Maintenance on a flat stable surface"><figcaption style="text-align:center;">[ Perform maintenance on a level, stable surface. ]</figcaption></figure><p>If unsure or something is wrong, contact Rainbow Robotics. See <a href="/RBQ/manual/Troubleshooting/error-reporting.html">Contact / Error Reporting</a>.</p>',12)])])}const b=t(l,[["render",i]]);export{p as __pageData,b as default};
